import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import f_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features by mean difference and t-test
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            if abs(mean_diff) > 0.5 and abs(t_stat) > 10:
                strong_features.append((fid, mean_diff, t_stat, p_val))

    # Sort by effect size
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated with |r| >= 0.6)
    to_remove = set()
    corr_pairs = [
        ('RAV7P', 'VXX13A'), ('IZR10', 'RTD16'), ('IZR10', 'BJZZ7'), ('KJJ16', 'WFC3'),
        ('IZR10', 'SXGM9L'), ('KJJ16', 'LVPE1B'), ('LVPE1B', 'WFC3'), ('IZR10', 'PFL10'),
        ('IZR10', 'HWXE18'), ('IZR10', 'XRU7'), ('RTD16', 'SXGM9L'), ('RFK10', 'SXGM9L'),
        ('RTD16', 'BJZZ7'), ('RFK10', 'IZR10'), ('SXGM9L', 'BJZZ7'), ('IZR10', 'IVS8A'),
        ('IZR10', 'WFC3'), ('RTD16', 'PFL10'), ('ROR17', 'IVS8A'), ('HWXE18', 'IVS8A')
    ]

    for a, b in corr_pairs:
        if a in feats.ids and b in feats.ids:
            idx_a = feats.column(a)
            idx_b = feats.column(b)
            if abs(np.corrcoef(feats.x[:, idx_a], feats.x[:, idx_b])[0, 1]) >= 0.6:
                # Prefer stronger feature
                a_idx = None
                b_idx = None
                for j, (fid, _, _, _) in enumerate(strong_features):
                    if fid == a:
                        a_idx = j
                    elif fid == b:
                        b_idx = j
                if a_idx is not None and b_idx is not None:
                    if strong_features[a_idx][1] > strong_features[b_idx][1]:
                        to_remove.add(b)
                    else:
                        to_remove.add(a)

    # Select drivers (top 5 non-correlated features)
    drivers = []
    for fid, _, _, _ in strong_features:
        if fid not in to_remove:
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # Build columns, products, and loadings
    columns = [fid for fid in feats.ids if fid not in to_remove]
    products = []
    loadings = {}

    # Simple weighted sum approach
    for i, fid in enumerate(columns):
        if feats.types[i] != 'derived':
            # Weight by effect size
            t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            loadings[fid] = abs(t_stat)

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
